/**
 * Exercise Apple SignedDataVerifier certificate-chain validation using Apple's published test vectors.
 * Usage: node scripts/run-apple-jws-library-chain-test.mjs
 */
import { X509Certificate } from "node:crypto";
import { SignedDataVerifier, VerificationException, VerificationStatus, Environment } from "@apple/app-store-server-library";
import { readFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
function loadAppleRootCertificates() {
    const certDir = join(repoRoot, "lib/apple/certs");
    const files = ["AppleRootCA-G3.cer", "AppleIncRootCertificate.cer", "AppleRootCA-G2.cer"];
    return files
        .map((name) => join(certDir, name))
        .filter((path) => existsSync(path))
        .map((path) => readFileSync(path));
}

let failed = false;

try {
    const mdbRoots = loadAppleRootCertificates();
    console.log(`PASS MDB loadAppleRootCertificates count=${mdbRoots.length}`);
    const realVerifier = new SignedDataVerifier(mdbRoots, false, Environment.SANDBOX, "com.digitalmusicdatabase.app");
    const realIntermediate = Buffer.from(
        "",
        "base64",
    );
    const realLeaf = Buffer.from(
        "",
        "base64",
    );
    await realVerifier.verifyCertificateChainWithoutCaching(
        realVerifier.rootCertificates,
        new X509Certificate(realLeaf),
        new X509Certificate(realIntermediate),
        new Date(1761962975000),
    );
    console.log("PASS MDB bundled Apple G3 roots validate real Apple WWDRG6 → leaf chain");
} catch (error) {
    if (error instanceof VerificationException) {
        console.error(`FAIL MDB real Apple chain status=${error.status}`);
    } else {
        console.error("FAIL MDB real Apple chain", error);
    }
    failed = true;
}

const sandboxVerifier = new SignedDataVerifier(
    loadAppleRootCertificates(),
    false,
    Environment.SANDBOX,
    "com.digitalmusicdatabase.app",
);

for (const [label, fn] of [
    ["malformed notification JWS", () => sandboxVerifier.verifyAndDecodeNotification("a.b.c")],
    ["malformed transaction JWS", () => sandboxVerifier.verifyAndDecodeTransaction("a.b.c")],
]) {
    try {
        await fn();
        console.error(`FAIL ${label} should not verify`);
        failed = true;
    } catch (error) {
        if (error instanceof VerificationException && error.status === VerificationStatus.VERIFICATION_FAILURE) {
            console.log(`PASS ${label} rejected (SignedDataVerifier, not decode-only)`);
        } else {
            console.error(`FAIL ${label} rejection`, error);
            failed = true;
        }
    }
}

process.exit(failed ? 1 : 0);
